import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useCreateWalletMutation } from '~/entities/wallet/api/use-create-wallet-mutation';
import { closeWebview } from '~/shared/api';
import { IDAuthType } from '~/shared/api/dtos/enums';
import { NativeFunction } from '~/shared/constants/native-function';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

type IDScanFunction = NativeFunction.IDScan | NativeFunction.BusinessLicenseScan | NativeFunction.PassportScan;
type RetakeButtonProps = {
  to: string;
  scanType: IDScanFunction;
  idauthTypeCd?: IDAuthType;
};

export const RetakeButton = ({
  to,
  scanType = NativeFunction.IDScan,
  idauthTypeCd = IDAuthType.주민,
}: RetakeButtonProps) => {
  const { navigate } = useNavigate();
  const { mutateAsync: createWallet } = useCreateWalletMutation();
  const { data: userRes } = useGetUserInfoQuery();

  const handleReTake = () => {
    window.webViewBridge.send(scanType, {
      success: () => {
        navigate(to, { replace: true });
      },
    });
  };

  const handleConfirm = async () => {
    const { result } = await createWallet({
      tbCstmrMastr: {
        cstmrNo: userRes?.tbCstmrMastr?.cstmrNo || '',
        idauthTypeCd: idauthTypeCd,
      },
    });
    if (result) {
      closeWebview({
        redirectPath: PATHS.home,
        notiBarMessage: `${userRes?.tbCstmrMastr?.koreanNm}님의 지갑이 생성되었어요!`,
      });
    }
  };

  return (
    <div className="btm-btn-area confirm">
      <button type="button" className="btm-btn" onClick={handleReTake}>
        {i18n.t('retake')}
      </button>
      <button type="button" className="btm-btn app" onClick={handleConfirm}>
        {i18n.t('confirm')}
      </button>
    </div>
  );
};
